import {transportLine} from './place-dialogue.js';
import {foodImage} from './food-images.js';
import {activeMeals,carryMeal,storeMeal,discardMeal} from './home-life.js';
import {ENTRANCES} from './neighbourhood.js';
import {FOOD_MENU,FOOD_ADDRESSES,DELIVERY_FEE,RIDE_STOPS,RIDE_SERVICES,activeFood,activeRide,activeCook,passenger,mealInfo,rideQuote,orderFood,cancelFood,receiveFood,eatMeal,bookRide,cancelRide,boardRide,requestEarlyStop,alightRide,startCooking,chopFood,setBurner,stirFood,cancelCooking,serveCooking} from './daily-life.js';
const money=n=>'₦'+n.toLocaleString();
const statusNames={preparing:'Preparing your meal',collecting:'Courier walking to Mama T’s',delivering:'Courier coming to your entrance',arrived:'Waiting for you',received:'Meal received',cancelled:'Cancelled & refunded',dispatching:'Vehicle on its way',waiting:'Ready to board',travelling:'On the road',complete:'Trip complete',ended:'Ride ended early'};
const resultOK=()=>({ok:true,message:''});
export function createFoodApp({container,state,routes,receive,commit,guide,location,position}){
 let menu='jollof',address='home',confirm=false,lastStatus='',disposed=false;
 const el=id=>container.querySelector('#'+id),act=r=>{commit(r);render();};
 function render(){if(disposed)return;const o=state.daily.order;lastStatus=o?.status||'';
 container.innerHTML='<div class="service-header"><span class="eyebrow">MAMA T’S KITCHEN</span><h3>A meal for your day.</h3><p>Physical delivery to an existing entrance. One plate per order.</p></div>';
 if(activeFood(state)){
  container.insertAdjacentHTML('beforeend','<div class="service-status"><span class="eyebrow">ORDER #'+o.id+'</span><h3 id="food-stage"></h3><p>'+FOOD_MENU[o.menu].name+' → '+ENTRANCES[o.address].name+'</p><progress id="food-progress" max="1" value="'+o.progress+'"></progress><p id="food-stage-detail"></p><button class="primary" id="food-guide">Show delivery entrance</button>'+(o.status==='arrived'?'<button class="primary" id="food-receive">Receive meal here</button>':'')+'<button class="secondary" id="food-cancel">Cancel order · full refund</button><div id="food-cancel-confirm"></div></div>');
  el('food-guide').onclick=()=>guide('food');if(el('food-receive'))el('food-receive').onclick=()=>receive();
  el('food-cancel').onclick=()=>{el('food-cancel-confirm').innerHTML='<p>Cancel order #'+o.id+' and refund '+money(o.total)+'?</p><button id="food-confirm-cancel" class="secondary">Confirm cancellation</button>';el('food-confirm-cancel').onclick=()=>act(cancelFood(state,o.id));};
 }else{
  if(o)container.insertAdjacentHTML('beforeend','<p class="service-receipt">Order #'+o.id+' · '+statusNames[o.status]+'</p>');
  container.insertAdjacentHTML('beforeend','<div class="food-menu">'+Object.entries(FOOD_MENU).map(([id,m])=>'<button id="meal-'+id+'" class="food-menu-card" aria-pressed="'+(menu===id)+'">'+foodImage(id)+'<strong>'+m.name+'</strong><span>'+money(m.price)+' · +'+m.food+' food when eaten</span></button>').join('')+'</div><label class="field">Deliver outside<select id="food-address">'+FOOD_ADDRESSES.map(id=>'<option value="'+id+'">'+ENTRANCES[id].name+' · '+ENTRANCES[id].address+'</option>').join('')+'</select></label><p>Delivery '+money(DELIVERY_FEE)+'. Total <strong>'+money(FOOD_MENU[menu].price+DELIVERY_FEE)+'</strong>.</p><p class="note">Full refund until you receive the meal. Collect outside the entrance using Action; ordering alone does not restore food.</p><button class="primary" id="food-review">Review order</button><div id="food-confirmation"></div>');
  el('food-address').value=address;el('food-address').onchange=()=>{address=el('food-address').value;confirm=false;el('food-confirmation').innerHTML='';};for(const id of Object.keys(FOOD_MENU))el('meal-'+id).onclick=()=>{menu=id;confirm=false;render();};
  el('food-review').onclick=()=>{const serial=state.daily.foodSerial,total=FOOD_MENU[menu].price+DELIVERY_FEE,selected=menu,destination=address;el('food-confirmation').innerHTML='<div class="purchase-confirm"><p>'+FOOD_MENU[selected].name+' to '+ENTRANCES[destination].name+'. Pay '+money(total)+' game currency now?</p><button id="food-confirm" class="primary">Confirm · '+money(total)+'</button><button id="food-back" class="secondary">Keep browsing</button></div>';el('food-back').onclick=()=>el('food-confirmation').innerHTML='';el('food-confirm').onclick=()=>act(orderFood(state,selected,destination,serial,routes));};
 }
 container.insertAdjacentHTML('beforeend','<section class="stored-meals"><h3>Your meals · '+activeMeals(state).length+'/20</h3><p class="note">Carry food through the door. Place/open/eat at the home table; store leftovers in your bag or fridge.</p>'+activeMeals(state).map(m=>'<div class="meal-row">'+foodImage(m.recipe)+'<span>'+mealInfo(m.recipe).name+' · '+m.phase+' · '+m.place+' · '+(4-m.bites)+'/4 left</span><button id="carry-'+m.id+'">Carry</button><button id="store-'+m.id+'">Store in bag</button><button id="discard-'+m.id+'">Discard…</button></div>').join('')+'<div id="meal-confirmation"></div></section>');for(const m of activeMeals(state)){el('carry-'+m.id).onclick=()=>act(carryMeal(state,m.id,location(),position()));el('store-'+m.id).onclick=()=>act(storeMeal(state,m.id,'bag',location(),position()));el('discard-'+m.id).onclick=()=>{el('meal-confirmation').innerHTML='<p>Discard this remaining meal? No food reward.</p><button id="confirm-discard">Discard meal</button>';el('confirm-discard').onclick=()=>act(discardMeal(state,m.id));};}tick();
 }
 function tick(){if(disposed)return;const o=state.daily.order;if((o?.status||'')!==lastStatus){render();return;}if(el('food-stage')){el('food-stage').textContent=statusNames[o.status];el('food-progress').value=o.progress;el('food-stage-detail').textContent=o.status==='arrived'?'Your courier will wait. Walk outside to receive the meal.':'This is a live local journey. Closing Phone keeps it moving; leaving the game pauses it.';}}
 render();return {kind:'food',tick,dispose(){disposed=true;}};
}
export function createRideApp({container,state,commit,guide,location,position,initialService='neighbourhood',atCounter=false,speak=()=>{},speakText=null}){
 let service=initialService,pickup=Object.hasOwn(RIDE_STOPS,location())?location():'home',destination=pickup==='shop'?'home':'shop',lastStatus='',disposed=false;
 const el=id=>container.querySelector('#'+id),act=(r,reply,response)=>{commit(r);render();if(!r?.ok&&el('transport-dialogue'))el('transport-dialogue').textContent='Transport attendant: '+r.message;const message=r?.message||'';if(speakText){speakText([{speaker:'Transport attendant',text:message}]);return;}speak(r?.ok?[...(reply?[reply]:[]),response||voiceStatus()]:[/dispatch bike/.test(message)?'ticketParkBike':/currency|balance/.test(message)?'ticketFunds':/counter/.test(message)?'ticketCounter':/pickup marker/.test(message)?'ticketBoardFirst':/Wait until|stopped/.test(message)?'ticketWaitStop':/stops/.test(message)?'ticketChoose':'ticketHandled']);};
 function voiceStatus(){return ({dispatching:'ticketDispatching',waiting:'ticketWaiting',travelling:'ticketTravelling',arrived:'ticketArrived',complete:'ticketComplete',ended:'ticketComplete',cancelled:'ticketRefund'})[state.daily.ride?.status]||'ticketHello';}
 function render(){if(disposed)return;const r=state.daily.ride;lastStatus=r?.status||'';
 container.innerHTML='<div class="service-header"><span class="eyebrow">NEIGHBOURHOOD RIDE</span><h3>Meet. Ride. Arrive.</h3><p>Car or yellow danfo · Home, Dispatch and Provisions.</p></div><p id="transport-dialogue" class="service-receipt" role="status">'+transportLine(state)+'</p>';
 if(activeRide(state)){
  container.insertAdjacentHTML('beforeend','<div class="service-status"><span class="eyebrow">'+RIDE_SERVICES[r.service||'neighbourhood'].name+' · TRIP #'+r.id+' · '+money(r.fare)+'</span><h3 id="ride-stage"></h3><p>'+RIDE_STOPS[r.pickup].name+' → '+RIDE_STOPS[r.dropoff].name+'</p><progress id="ride-progress" max="1" value="'+r.progress+'"></progress><p id="ride-detail"></p>'+(!passenger(state)?'<button id="ride-guide" class="primary">Show pickup marker</button>':'')+(r.status==='waiting'?'<button id="ride-board" class="primary">Board here</button>':'')+(r.status==='arrived'?'<button id="ride-alight" class="primary">Get out at this stop</button>':'')+(['dispatching','waiting'].includes(r.status)?'<button id="ride-cancel" class="secondary">Cancel · full fare refund</button>':r.status==='travelling'&&!r.early?'<button id="ride-early" class="secondary">Request next safe stop</button>':'')+'<div id="ride-confirmation"></div></div>');
  if(el('ride-guide'))el('ride-guide').onclick=()=>guide('ride');if(el('ride-board'))el('ride-board').onclick=()=>act(boardRide(state,r.id,location(),position()),'playerBoard');if(el('ride-alight'))el('ride-alight').onclick=()=>act(alightRide(state,r.id),'playerAlight');
  if(el('ride-cancel'))el('ride-cancel').onclick=()=>{el('ride-confirmation').innerHTML='<p>Cancel trip #'+r.id+' and refund '+money(r.fare)+'?</p><button id="ride-confirm-cancel" class="secondary">Confirm cancellation</button>';el('ride-confirm-cancel').onclick=()=>act(cancelRide(state,r.id),'playerCancelRide');};
  if(el('ride-early'))el('ride-early').onclick=()=>{el('ride-confirmation').innerHTML='<p>The vehicle will drive to the next safe stop. The agreed fare is retained.</p><button id="ride-confirm-early" class="secondary">Confirm early drop-off</button>';el('ride-confirm-early').onclick=()=>{const result=requestEarlyStop(state,r.id);act(result,'playerEarly','ticketEarly');};};
 }else{
  if(r)container.insertAdjacentHTML('beforeend','<p class="service-receipt">Trip #'+r.id+' · '+statusNames[r.status]+'</p>');
  const options=Object.entries(RIDE_STOPS).map(([id,s])=>'<option value="'+id+'">'+s.name+'</option>').join('');container.insertAdjacentHTML('beforeend','<label class="field">Service<select id="ride-service">'+Object.entries(RIDE_SERVICES).map(([id,v])=>'<option value="'+id+'">'+v.name+'</option>').join('')+'</select></label><label class="field">Pickup<select id="ride-pickup">'+options+'</select></label><label class="field">Destination<select id="ride-destination">'+options+'</select></label><p id="ride-quote"></p><p class="note">Fare is charged once on confirmation. Full refund before boarding. After boarding, early drop-off is at the next safe stop with no fare refund. The vehicle waits until you board.</p><button id="ride-review" class="primary">Review booking</button><div id="ride-confirmation"></div>');
  el('ride-service').value=service;el('ride-pickup').value=pickup;el('ride-destination').value=destination;const quote=()=>{const q=rideQuote(pickup,destination,service);el('ride-quote').textContent=q?'Fare: '+money(q.fare)+' game currency. Walk to the marked roadside pickup.':'Choose two different stops.';el('ride-review').disabled=!q;el('ride-confirmation').innerHTML='';};for(const key of ['pickup','destination','service'])el('ride-'+key).onchange=()=>{service=el('ride-service').value;pickup=el('ride-pickup').value;destination=el('ride-destination').value;quote();const q=rideQuote(pickup,destination,service);speak([q?'fare'+q.fare:'ticketChoose']);};quote();
  el('ride-review').onclick=()=>{const q=rideQuote(pickup,destination,service);if(!q){speak(['ticketChoose']);return;}speak(['fare'+q.fare]);const from=pickup,to=destination,selectedService=service,serial=state.daily.rideSerial;el('ride-confirmation').innerHTML='<div class="purchase-confirm"><p>'+RIDE_SERVICES[selectedService].name+' · '+RIDE_STOPS[from].name+' → '+RIDE_STOPS[to].name+'. Pay '+money(q.fare)+' now?</p><button id="ride-confirm" class="primary">Confirm · '+money(q.fare)+'</button><button id="ride-back" class="secondary">Keep browsing</button></div>';el('ride-back').onclick=()=>el('ride-confirmation').innerHTML='';el('ride-confirm').onclick=()=>act(atCounter&&(location()!=='dispatch'||Math.hypot(position().x+2.5,position().z+1.55)>1.25)?{ok:false,message:'Return to the ticket counter before confirming.'}:bookRide(state,from,to,serial,selectedService),'playerBook');};
 }tick();}
 function tick(){if(disposed)return;const r=state.daily.ride;if((r?.status||'')!==lastStatus){render();speak([voiceStatus()]);return;}if(el('ride-stage')){el('ride-stage').textContent=statusNames[r.status];el('ride-progress').value=r.progress;el('ride-detail').textContent=r.status==='travelling'?'The vehicle follows the street loop. Close Phone to watch your journey.':r.status==='waiting'?'Find your '+RIDE_SERVICES[r.service||'neighbourhood'].name+' at the gold pickup marker, then use Action to board.':r.status==='arrived'?'The vehicle is stopped. Get out to continue walking.':'Your vehicle is driving from the north end of the neighbourhood.';}}
 render();speak([voiceStatus()]);return {kind:'ride',tick,dispose(){disposed=true;}};
}
export function createCookingUI({container,state,commit,location,position,pause,food}){
 let lastStage='',disposed=false;const el=id=>container.querySelector('#'+id),act=r=>{commit(r);render();};
 function render(){if(disposed)return;const c=state.daily.cook;lastStage=c?.status||'';container.innerHTML='<span class="eyebrow">AT YOUR HOME COOKER</span><h2>One pot of jollof.</h2><p>Chop vegetables, manage the heat and stir. Serve after at least 10 seconds. A good plate needs four seconds in the green band and two stirs.</p>';
 if(!activeCook(state)){if(c?.status==='complete')container.insertAdjacentHTML('beforeend','<div class="cooking-result"><h3>'+(c.quality==='good'?'Nicely cooked.':'A little practice for next time.')+'</h3><p>Your plate is stored in Phone → Food.</p><button id="cook-meals" class="secondary">Open stored meals</button></div>');const serial=state.daily.cookSerial;container.insertAdjacentHTML('beforeend','<p>'+state.pantry+' groceries available. One grocery is reserved at the start. Cancel before heating to get it back; after heating it is used. Closing pauses the activity.</p><button id="cook-start" class="primary">Start cooking · 1 grocery</button>');el('cook-start').onclick=()=>act(startCooking(state,serial,location(),position()));if(el('cook-meals'))el('cook-meals').onclick=food;
 }else if(c.status==='prep'){container.insertAdjacentHTML('beforeend','<div class="cooking-pot" aria-hidden="true">◒</div><p>Vegetables chopped: '+c.chops+' / 3</p><button id="cook-chop" class="primary">Chop vegetables</button>');el('cook-chop').onclick=()=>act(chopFood(state,c.id));}
 else{container.insertAdjacentHTML('beforeend','<div class="cooking-pot" aria-hidden="true">◒</div><label class="field">Heat · keep between 55 and 75<meter id="cook-heat" min="0" max="100" low="55" high="75" optimum="65" value="'+c.heat+'"></meter></label><p id="cook-readout" role="status"></p><label class="field">Burner setting<input id="cook-burner" type="range" min="0" max="100" step="5" value="'+c.burner+'"></label><div class="cooking-buttons"><button id="cook-stir" class="secondary">Stir the pot</button><button id="cook-serve" class="primary">Serve & store meal</button></div>');el('cook-burner').oninput=()=>setBurner(state,c.id,Number(el('cook-burner').value));el('cook-burner').onchange=()=>commit(resultOK());el('cook-stir').onclick=()=>{commit(stirFood(state,c.id));tick();};el('cook-serve').onclick=()=>act(serveCooking(state,c.id));}
 if(activeCook(state)){container.insertAdjacentHTML('beforeend','<button id="cook-pause" class="secondary">Pause & return later</button><button id="cook-cancel" class="text-button">Cancel this meal</button><div id="cook-confirmation"></div>');el('cook-pause').onclick=pause;el('cook-cancel').onclick=()=>{el('cook-confirmation').innerHTML='<p>'+(c.status==='prep'?'Cancel and return the grocery?':'The stove has started. Cancel and discard this ingredient?')+'</p><button id="cook-confirm-cancel" class="secondary">Confirm cancellation</button>';el('cook-confirm-cancel').onclick=()=>act(cancelCooking(state,c.id));};}tick();
 }
 function tick(){if(disposed)return;const c=state.daily.cook;if((c?.status||'')!==lastStage){render();return;}if(el('cook-heat')){el('cook-heat').value=c.heat;el('cook-readout').textContent='Heat '+Math.round(c.heat)+' · '+Math.floor(c.elapsed)+' seconds · green band '+Math.floor(c.good)+'/4 seconds · stirs '+c.stirs+'/2';el('cook-stir').disabled=c.sinceStir<2;el('cook-serve').disabled=c.elapsed<10;}}
 render();return {kind:'cook',tick,dispose(){disposed=true;}};
}
